"use client";

import { useState, type ReactNode } from "react";
import { Loader2, Share2 } from "lucide-react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { whatsappDigits } from "@/lib/phone";
import { fr } from "@/messages/fr";

/**
 * Shares images generated by the app (receipts, stock sheet pages) and a text through the
 * phone's share sheet (WhatsApp…), all images at once. Without file sharing (most desktops),
 * downloads the images and opens WhatsApp with the text.
 */
export function ShareImageButton({
  files,
  title,
  text,
  phone,
  label,
  iconOnly = false,
  variant = "whatsapp",
  className,
  icon,
}: {
  files: { url: string; name: string }[];
  title: string;
  text: string;
  /** WhatsApp number to open on desktop, if known. */
  phone: string | null;
  label: string;
  iconOnly?: boolean;
  variant?: "whatsapp" | "ghost" | "outline";
  className?: string;
  icon?: ReactNode;
}) {
  const [busy, setBusy] = useState(false);

  const share = async () => {
    setBusy(true);
    try {
      const images = await Promise.all(
        files.map(async ({ url, name }) => {
          const response = await fetch(url);
          if (!response.ok) throw new Error(String(response.status));
          return new File([await response.blob()], name, { type: "image/png" });
        }),
      );

      if (navigator.canShare?.({ files: images })) {
        await navigator.share({ files: images, text, title });
        return;
      }

      for (const image of images) {
        const objectUrl = URL.createObjectURL(image);
        const link = document.createElement("a");
        link.href = objectUrl;
        link.download = image.name;
        link.click();
        URL.revokeObjectURL(objectUrl);
      }
      const target = phone ? whatsappDigits(phone) : "";
      window.open(`https://wa.me/${target}?text=${encodeURIComponent(text)}`, "_blank", "noopener");
    } catch (error) {
      // Closing the share sheet is not an error.
      if (error instanceof DOMException && error.name === "AbortError") return;
      toast.error(fr.errors.UNKNOWN);
    } finally {
      setBusy(false);
    }
  };

  const glyph = busy ? (
    <Loader2 aria-hidden="true" className="animate-spin" />
  ) : (
    (icon ?? <Share2 aria-hidden="true" />)
  );

  return iconOnly ? (
    <Button variant="ghost" size="icon-sm" aria-label={label} onClick={share} disabled={busy}>
      {glyph}
    </Button>
  ) : (
    <Button variant={variant} onClick={share} disabled={busy} className={className}>
      {glyph}
      {label}
    </Button>
  );
}
